func main() {
	argv0 := os.Args[0]
	args := os.Args[1:]

	if len(args) == 0 {
		os.Exit(runDocGen("Doxyfile", false))
	}

	shortMode := false
	quietMode := false
	var configFile string
	var dLevels []string

	for i := 0; i < len(args); i++ {
		arg := args[i]

		if arg == "-v" {
			fmt.Println(versionString)
			os.Exit(0)
		} else if arg == "-V" {
			fmt.Println(fullVersion)
			os.Exit(0)
		} else if arg == "-h" || arg == "-?" || arg == "--help" {
			fmt.Print(getUsage(argv0))
