			}
			asset := "assets/Doxyfile.default"
			if shortMode {
				asset = "assets/Doxyfile.short"
			}
			err := writeAsset(asset, configName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", configName, err)
				os.Exit(1)
			}
			if configName != "-" {
				cmdSuffix := ""
				if configName != "Doxyfile" {
					cmdSuffix = " " + configName
				}
				fmt.Printf("\n\nConfiguration file '%s' created.\n\nNow edit the configuration file and enter\n\n  doxygen%s\n\nto generate the documentation for your project\n\n", configName, cmdSuffix)
			}
			os.Exit(0)
		} else if arg == "-u" {
			configName := "Doxyfile"
			if i+1 < len(args) && (!strings.HasPrefix(args[i+1], "-") || args[i+1] == "-") {
				i++
				configName = args[i]
			}
			asset := "assets/Doxyfile.default"
			if shortMode {
				asset = "assets/Doxyfile.short"
			}
			err := writeAsset(asset, configName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: failed to update %s: %v\n", configName, err)
				os.Exit(1)
			}
			if configName != "-" {
