func mangleFileName(name string) string {
	var res strings.Builder
	for _, ch := range name {
		if (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') {
			res.WriteRune(ch)
		} else if ch == '.' {
			res.WriteString("_8")
		} else if ch == '_' {
			res.WriteString("__")
		} else if ch == '-' {
			res.WriteString("_01")
		} else {
			res.WriteString(fmt.Sprintf("_%02x", ch))
		}
	}
	return res.String()
}

