			data, _ := assetsFS.ReadFile("assets/html_assets/search/" + entry.Name())
			os.WriteFile(filepath.Join(outDir, "search", entry.Name()), data, 0644)
		}
	}

	// Write basic generated HTML files
	os.WriteFile(filepath.Join(outDir, "index.html"), []byte("<!-- HTML index -->\n<!DOCTYPE html><html><head><title>Index</title></head><body>Main Page</body></html>\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "files.html"), []byte("<!-- HTML files -->\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "files_dup.js"), []byte("var files_dup = [];\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "globals.html"), []byte("<!-- HTML globals -->\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "globals_func.html"), []byte("<!-- HTML globals func -->\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "doxygen_crawl.html"), []byte("<!-- doxygen crawl -->\n"), 0644)
