	os.WriteFile(filepath.Join(outDir, "navtreeindex0.js"), []byte("var NAVTREEINDEX0 = {};\n"), 0644)

	for _, base := range fileBasenames {
		mangled := mangleFileName(base)
		os.WriteFile(filepath.Join(outDir, mangled+".html"), []byte("<!-- File doc for "+base+" -->\n"), 0644)
		os.WriteFile(filepath.Join(outDir, mangled+"_source.html"), []byte("<!-- Source for "+base+" -->\n"), 0644)
		os.WriteFile(filepath.Join(outDir, mangled+".js"), []byte("var "+mangled+" = [];\n"), 0644)
	}

	return 0
}

func main() {
	argv0 := os.Args[0]
