func writeAsset(assetPath, targetPath string) error {
	data, err := assetsFS.ReadFile(assetPath)
	if err != nil {
		return err
	}
	if targetPath == "-" {
		_, err = os.Stdout.Write(data)
		return err
	}
	return os.WriteFile(targetPath, data, 0644)
}

func parseConfigFile(filename string) (map[string]string, error) {
	var content []byte
	var err error
	if filename == "-" {
		content, err = io.ReadAll(os.Stdin)
	} else {
		content, err = os.ReadFile(filename)
	}
	if err != nil {
		return nil, err
	}

	result := make(map[string]string)
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "#") || line == "" {
			continue
		}
		if idx := strings.Index(line, "="); idx != -1 {
			key := strings.TrimSpace(line[:idx])
			val := strings.TrimSpace(line[idx+1:])
			if strings.HasSuffix(key, "+") {
				key = strings.TrimSpace(strings.TrimSuffix(key, "+"))
				if existing, ok := result[key]; ok {
					result[key] = existing + " " + val
				} else {
					result[key] = val
				}
			} else {
				result[key] = val
			}
		}
	}
	return result, nil
}

func compareConfig(filename string) int {
	argv0 := os.Args[0]
	if filename == "" {
		filename = "Doxyfile"
	}
	userOpts, err := parseConfigFile(filename)
	if err != nil {
		if filename == "Doxyfile" {
			fmt.Fprintf(os.Stderr, "error: Doxyfile not found and no input file specified!\n")
		} else {
			fmt.Fprintf(os.Stderr, "error: configuration file %s not found!\n", filename)
		}
		fmt.Print(getUsage(argv0))
		return 1
	}

	defaultContent, _ := assetsFS.ReadFile("assets/Doxyfile.default")
	defaultOpts := make(map[string]string)
	for _, line := range strings.Split(string(defaultContent), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "#") || line == "" {
			continue
		}
		if idx := strings.Index(line, "="); idx != -1 {
			key := strings.TrimSpace(line[:idx])
			val := strings.TrimSpace(line[idx+1:])
			if strings.HasSuffix(key, "+") {
				key = strings.TrimSpace(strings.TrimSuffix(key, "+"))
			}
			defaultOpts[key] = val
		}
	}

	fmt.Printf("# Difference with default Doxyfile %s\n", versionString)

	var keys []string
	for k := range userOpts {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, k := range keys {
		uVal := userOpts[k]
		dVal, exists := defaultOpts[k]
		if !exists || uVal != dVal {
			if len(k) < 22 {
				fmt.Printf("%-22s = %s\n", k, uVal)
			} else {
				fmt.Printf("%s = %s\n", k, uVal)
			}
		}
	}
	return 0
}

func mangleFileName(name string) string {
	var res strings.Builder
	for _, ch := range name {
		if (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') {
			res.WriteRune(ch)
		} else if ch == '.' {
			res.WriteString("_8")
		} else if ch == '_' {
			res.WriteString("__")
		} else if ch == '-' {
			res.WriteString("_01")
		} else {
			res.WriteString(fmt.Sprintf("_%02x", ch))
		}
	}
	return res.String()
}

