			err := writeAsset("assets/DoxygenLayout.xml", layoutName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", layoutName, err)
				os.Exit(1)
			}
			os.Exit(0)
		} else if arg == "-f" || strings.HasPrefix(arg, "-f") {
			spec := ""
			if arg == "-f" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-f\" is missing list specifier.\n")
					os.Exit(1)
				}
				i++
				spec = args[i]
			} else {
				spec = arg[2:]
			}
			if spec != "emoji" {
				fmt.Fprintf(os.Stderr, "error: option \"-f\" has invalid list specifier.\n")
				os.Exit(1)
			}
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "error: option \"-f emoji\" is missing an output file name\n")
				os.Exit(1)
			}
			i++
			outName := args[i]
			err := writeAsset("assets/emoji.txt", outName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", outName, err)
				os.Exit(1)
			}
			os.Exit(0)
		} else if arg == "-w" || strings.HasPrefix(arg, "-w") {
			fmtType := ""
			if arg == "-w" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-w\" is missing format specifier rtf, html or latex\n")
					os.Exit(1)
				}
				i++
				fmtType = args[i]
			} else {
				fmtType = arg[2:]
			}
			if fmtType == "rtf" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-w rtf\" is missing a style sheet file name\n")
					os.Exit(1)
				}
				i++
				outName := args[i]
				err := writeAsset("assets/style.rtf", outName)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", outName, err)
					os.Exit(1)
				}
				os.Exit(0)
			} else if fmtType == "html" {
				if i+3 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-w html\" does not have enough arguments\n")
					os.Exit(1)
				}
				hName := args[i+1]
				fName := args[i+2]
				sName := args[i+3]
				i += 3
				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
					i++ // optional configFile
				}
				writeAsset("assets/header.html", hName)
				writeAsset("assets/footer.html", fName)
				writeAsset("assets/style.css", sName)
				os.Exit(0)
			} else if fmtType == "latex" {
				if i+3 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-w latex\" does not have enough arguments\n")
					os.Exit(1)
				}
				hName := args[i+1]
				fName := args[i+2]
				sName := args[i+3]
				i += 3
				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
					i++ // optional configFile
				}
				writeAsset("assets/header.tex", hName)
				writeAsset("assets/footer.tex", fName)
				writeAsset("assets/style.sty", sName)
				os.Exit(0)
			} else {
				fmt.Fprintf(os.Stderr, "error: Illegal format specifier \"%s\": should be one of rtf, html or latex\n", fmtType)
				os.Exit(1)
			}
		} else if arg == "-e" || strings.HasPrefix(arg, "-e") {
			fmtType := ""
			if arg == "-e" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-e\" is missing format specifier rtf.\n")
					os.Exit(1)
				}
				i++
				fmtType = args[i]
			} else {
				fmtType = arg[2:]
			}
			if fmtType == "rtf" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-e rtf\" is missing an extensions file name\n")
					os.Exit(1)
				}
				i++
				outName := args[i]
				err := writeAsset("assets/ext.rtf", outName)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", outName, err)
					os.Exit(1)
				}
				os.Exit(0)
			} else {
				fmt.Fprintf(os.Stderr, "error: option \"-e\" has invalid format specifier.\n")
				os.Exit(1)
			}
		} else if arg == "-x" || arg == "-x_noenv" || strings.HasPrefix(arg, "-x") {
			if arg == "-x" || arg == "-x_noenv" {
				cfgFile := ""
				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
					i++
					cfgFile = args[i]
				}
				os.Exit(compareConfig(cfgFile))
			} else {
				fmt.Fprintf(os.Stderr, "error: option should be \"-x\" or \"-x_noenv\", found: \"%s\".\n", arg)
				os.Exit(1)
			}
		} else if strings.HasPrefix(arg, "-") {
			opt := arg
			if !strings.HasPrefix(arg, "--") && len(arg) > 2 {
				opt = arg[:2]
			}
			fmt.Fprintf(os.Stderr, "error: Unknown option \"%s\"\n", opt)
			fmt.Print(getUsage(argv0))
			os.Exit(1)
		} else {
			configFile = arg
		}
	}

	_ = dLevels
	os.Exit(runDocGen(configFile, quietMode))
}
