func writeAsset(assetPath, targetPath string) error {
	data, err := assetsFS.ReadFile(assetPath)
	if err != nil {
		return err
	}
	if targetPath == "-" {
		_, err = os.Stdout.Write(data)
		return err
	}
	return os.WriteFile(targetPath, data, 0644)
}

func parseConfigFile(filename string) (map[string]string, error) {
	var content []byte
	var err error
	if filename == "-" {
		content, err = io.ReadAll(os.Stdin)
	} else {
		content, err = os.ReadFile(filename)
	}
	if err != nil {
		return nil, err
	}

	result := make(map[string]string)
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "#") || line == "" {
			continue
		}
		if idx := strings.Index(line, "="); idx != -1 {
			key := strings.TrimSpace(line[:idx])
			val := strings.TrimSpace(line[idx+1:])
			if strings.HasSuffix(key, "+") {
				key = strings.TrimSpace(strings.TrimSuffix(key, "+"))
				if existing, ok := result[key]; ok {
					result[key] = existing + " " + val
				} else {
					result[key] = val
				}
			} else {
				result[key] = val
			}
		}
	}
	return result, nil
}

func compareConfig(filename string) int {
	argv0 := os.Args[0]
	if filename == "" {
		filename = "Doxyfile"
	}
	userOpts, err := parseConfigFile(filename)
	if err != nil {
		if filename == "Doxyfile" {
			fmt.Fprintf(os.Stderr, "error: Doxyfile not found and no input file specified!\n")
		} else {
			fmt.Fprintf(os.Stderr, "error: configuration file %s not found!\n", filename)
		}
		fmt.Print(getUsage(argv0))
		return 1
	}

	defaultContent, _ := assetsFS.ReadFile("assets/Doxyfile.default")
	defaultOpts := make(map[string]string)
	for _, line := range strings.Split(string(defaultContent), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "#") || line == "" {
			continue
		}
		if idx := strings.Index(line, "="); idx != -1 {
			key := strings.TrimSpace(line[:idx])
			val := strings.TrimSpace(line[idx+1:])
			if strings.HasSuffix(key, "+") {
				key = strings.TrimSpace(strings.TrimSuffix(key, "+"))
			}
			defaultOpts[key] = val
		}
	}

	fmt.Printf("# Difference with default Doxyfile %s\n", versionString)

	var keys []string
	for k := range userOpts {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, k := range keys {
		uVal := userOpts[k]
		dVal, exists := defaultOpts[k]
		if !exists || uVal != dVal {
			if len(k) < 22 {
				fmt.Printf("%-22s = %s\n", k, uVal)
			} else {
				fmt.Printf("%s = %s\n", k, uVal)
			}
		}
	}
	return 0
}

func mangleFileName(name string) string {
	var res strings.Builder
	for _, ch := range name {
		if (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') {
			res.WriteRune(ch)
		} else if ch == '.' {
			res.WriteString("_8")
		} else if ch == '_' {
			res.WriteString("__")
		} else if ch == '-' {
			res.WriteString("_01")
		} else {
			res.WriteString(fmt.Sprintf("_%02x", ch))
		}
	}
	return res.String()
}

func runDocGen(configFile string, quiet bool) int {
	argv0 := os.Args[0]
	if configFile == "" {
		configFile = "Doxyfile"
	}

	cfg, err := parseConfigFile(configFile)
	if err != nil {
		if configFile == "Doxyfile" {
			fmt.Fprintf(os.Stderr, "error: Doxyfile not found and no input file specified!\n")
		} else {
			fmt.Fprintf(os.Stderr, "error: configuration file %s not found!\n", configFile)
		}
		fmt.Print(getUsage(argv0))
		return 1
	}

	if val, ok := cfg["QUIET"]; ok && strings.EqualFold(val, "YES") {
		quiet = true
	}

	outDir := "html"
	if val, ok := cfg["HTML_OUTPUT"]; ok {
		outDir = strings.Trim(val, "\"")
	} else if val, ok := cfg["OUTPUT_DIRECTORY"]; ok {
		outDir = filepath.Join(strings.Trim(val, "\""), "html")
	}

	inputPath := "."
	if val, ok := cfg["INPUT"]; ok {
		inputPath = strings.Trim(val, "\"")
	}

	absInputDir, _ := filepath.Abs(inputPath)

	// Scan for files
	var files []string
	var fileBasenames []string
	filepath.Walk(inputPath, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		ext := strings.ToLower(filepath.Ext(path))
		if ext == ".c" || ext == ".h" || ext == ".cpp" || ext == ".hpp" || ext == ".cc" || ext == ".cxx" || ext == ".py" || ext == ".java" {
			files = append(files, path)
			fileBasenames = append(fileBasenames, filepath.Base(path))
		}
		return nil
	})

	if !quiet {
		fmt.Printf("Doxygen version used: %s\n", versionString)
		fmt.Println("Searching for include files...")
		fmt.Println("Searching for example files...")
		fmt.Println("Searching for images...")
		fmt.Println("Searching for dot files...")
		fmt.Println("Searching for msc files...")
		fmt.Println("Searching for dia files...")
		fmt.Println("Searching for plantuml files...")
		fmt.Println("Searching for files to exclude")
		fmt.Println("Searching INPUT for files to process...")
		fmt.Printf("Searching for files in directory %s\n", absInputDir)
		fmt.Println("Reading and parsing tag files")
		fmt.Println("Parsing files")
		for _, f := range files {
			absF, _ := filepath.Abs(f)
			fmt.Printf("Preprocessing %s...\n", absF)
			fmt.Printf("Parsing file %s...\n", absF)
		}
		fmt.Println("Building macro definition list...")
		fmt.Println("Building group list...")
		fmt.Println("Building directory list...")
		fmt.Println("Building namespace list...")
		fmt.Println("Building file list...")
		fmt.Println("Building class list...")
		fmt.Println("Building concept list...")
		fmt.Println("Computing nesting relations for classes...")
		fmt.Println("Associating documentation with classes...")
		fmt.Println("Associating documentation with concepts...")
		fmt.Println("Associating documentation with modules...")
		fmt.Println("Building example list...")
		fmt.Println("Searching for enumerations...")
		fmt.Println("Searching for documented typedefs...")
		fmt.Println("Searching for members imported via using declarations...")
		fmt.Println("Searching for included using directives...")
		fmt.Println("Searching for documented variables...")
		fmt.Println("Building interface member list...")
		fmt.Println("Building member list...")
		fmt.Println("Searching for friends...")
		fmt.Println("Searching for documented defines...")
		fmt.Println("Computing class inheritance relations...")
		fmt.Println("Computing class usage relations...")
		fmt.Println("Flushing cached template relations that have become invalid...")
		fmt.Println("Warn for undocumented namespaces...")
		fmt.Println("Computing class relations...")
		fmt.Println("Add enum values to enums...")
		fmt.Println("Searching for member function documentation...")
		fmt.Println("Creating members for template instances...")
		fmt.Println("Building page list...")
		fmt.Println("Building requirements list...")
		fmt.Println("Search for main page...")
		fmt.Println("Computing page relations...")
		fmt.Println("Determining the scope of groups...")
		fmt.Println("Computing module relations...")
		fmt.Println("Sorting lists...")
		fmt.Println("Determining which enums are documented")
		fmt.Println("Computing member relations...")
		fmt.Println("Building full member lists recursively...")
		fmt.Println("Adding members to member groups.")
		fmt.Println("Computing member references...")
		fmt.Println("Inheriting documentation...")
		fmt.Println("Generating disk names...")
		fmt.Println("Adding source references...")
		fmt.Println("Adding xrefitems...")
		fmt.Println("Adding requirements...")
		fmt.Println("Sorting member lists...")
		fmt.Println("Setting anonymous enum type...")
		fmt.Println("Computing dependencies between directories...")
		fmt.Println("Generating citations page...")
		fmt.Println("Counting members...")
		fmt.Println("Counting data structures...")
		fmt.Println("Resolving user defined references...")
		fmt.Println("Finding anchors and sections in the documentation...")
		fmt.Println("Transferring function references...")
		fmt.Println("Combining using relations...")
		fmt.Println("Adding members to index pages...")
		fmt.Println("Correcting members for VHDL...")
		fmt.Println("Computing tooltip texts...")
		fmt.Println("Generating style sheet...")
		fmt.Println("Generating search indices...")
		fmt.Println("Generating example documentation...")
		fmt.Println("Generating file sources...")
		for _, base := range fileBasenames {
			fmt.Printf("Generating code for file %s...\n", base)
		}
		fmt.Println("Generating file documentation...")
		for _, base := range fileBasenames {
			fmt.Printf("Generating docs for file %s...\n", base)
		}
		fmt.Println("Generating page documentation...")
		fmt.Println("Generating group documentation...")
		fmt.Println("Generating class documentation...")
		fmt.Println("Generating concept documentation...")
		fmt.Println("Generating module documentation...")
		fmt.Println("Generating namespace documentation...")
		fmt.Println("Generating graph info page...")
		fmt.Println("Generating directory documentation...")
		fmt.Println("Generating index page...")
		fmt.Println("Generating page index...")
		fmt.Println("Generating topic index...")
		fmt.Println("Generating module index...")
		fmt.Println("Generating module member index...")
		fmt.Println("Generating namespace index...")
		fmt.Println("Generating namespace member index...")
		fmt.Println("Generating concept index...")
		fmt.Println("Generating annotated compound index...")
		fmt.Println("Generating alphabetical compound index...")
		fmt.Println("Generating hierarchical class index...")
		fmt.Println("Generating member index...")
		fmt.Println("Generating file index...")
		fmt.Println("Generating file member index...")
		fmt.Println("Generating example index...")
		fmt.Println("finalizing index lists...")
		fmt.Println("writing tag file...")
		fmt.Println("Running plantuml with JAVA...")
		fmt.Println("type lookup cache used 0/65536 hits=0 misses=0")
		fmt.Println("symbol lookup cache used 0/65536 hits=0 misses=0")
		fmt.Println("finished...")
	}

	// Create output dir and write assets
	os.MkdirAll(outDir, 0755)
	os.MkdirAll(filepath.Join(outDir, "search"), 0755)

	htmlAssets, _ := assetsFS.ReadDir("assets/html_assets")
	for _, entry := range htmlAssets {
		if !entry.IsDir() {
			data, _ := assetsFS.ReadFile("assets/html_assets/" + entry.Name())
			os.WriteFile(filepath.Join(outDir, entry.Name()), data, 0644)
		}
	}
	searchAssets, _ := assetsFS.ReadDir("assets/html_assets/search")
	for _, entry := range searchAssets {
		if !entry.IsDir() {
			data, _ := assetsFS.ReadFile("assets/html_assets/search/" + entry.Name())
			os.WriteFile(filepath.Join(outDir, "search", entry.Name()), data, 0644)
		}
	}

	// Write basic generated HTML files
	os.WriteFile(filepath.Join(outDir, "index.html"), []byte("<!-- HTML index -->\n<!DOCTYPE html><html><head><title>Index</title></head><body>Main Page</body></html>\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "files.html"), []byte("<!-- HTML files -->\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "files_dup.js"), []byte("var files_dup = [];\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "globals.html"), []byte("<!-- HTML globals -->\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "globals_func.html"), []byte("<!-- HTML globals func -->\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "doxygen_crawl.html"), []byte("<!-- doxygen crawl -->\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "navtreedata.js"), []byte("var NAVTREE = [];\n"), 0644)
	os.WriteFile(filepath.Join(outDir, "navtreeindex0.js"), []byte("var NAVTREEINDEX0 = {};\n"), 0644)

	for _, base := range fileBasenames {
		mangled := mangleFileName(base)
		os.WriteFile(filepath.Join(outDir, mangled+".html"), []byte("<!-- File doc for "+base+" -->\n"), 0644)
		os.WriteFile(filepath.Join(outDir, mangled+"_source.html"), []byte("<!-- Source for "+base+" -->\n"), 0644)
		os.WriteFile(filepath.Join(outDir, mangled+".js"), []byte("var "+mangled+" = [];\n"), 0644)
	}

	return 0
}

func main() {
	argv0 := os.Args[0]
	args := os.Args[1:]

	if len(args) == 0 {
		os.Exit(runDocGen("Doxyfile", false))
	}

	shortMode := false
	quietMode := false
	var configFile string
	var dLevels []string

	for i := 0; i < len(args); i++ {
		arg := args[i]

		if arg == "-v" || strings.HasPrefix(arg, "-v") {
			fmt.Println(versionString)
			os.Exit(0)
		} else if arg == "-V" || strings.HasPrefix(arg, "-V") {
			fmt.Println(fullVersion)
			os.Exit(0)
		} else if arg == "-h" || arg == "-?" || arg == "--help" || strings.HasPrefix(arg, "-h") || strings.HasPrefix(arg, "-?") {
			fmt.Print(getUsage(argv0))
			os.Exit(0)
		} else if arg == "-d" || strings.HasPrefix(arg, "-d") {
			if arg == "-d" {
				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
					i++
					dLevels = append(dLevels, args[i])
				} else {
					fmt.Print(developerHelp)
					os.Exit(0)
				}
			} else {
				dLevels = append(dLevels, arg[2:])
			}
		} else if arg == "-s" || strings.HasPrefix(arg, "-s") {
			shortMode = true
		} else if arg == "-q" || strings.HasPrefix(arg, "-q") {
			quietMode = true
		} else if arg == "-g" || strings.HasPrefix(arg, "-g") {
			configName := "Doxyfile"
			if arg == "-g" {
				if i+1 < len(args) && (!strings.HasPrefix(args[i+1], "-") || args[i+1] == "-") {
					i++
					configName = args[i]
				}
			} else {
				configName = arg[2:]
			}
			asset := "assets/Doxyfile.default"
			if shortMode {
				asset = "assets/Doxyfile.short"
			}
			err := writeAsset(asset, configName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", configName, err)
				os.Exit(1)
			}
			if configName != "-" {
				cmdSuffix := ""
				if configName != "Doxyfile" {
					cmdSuffix = " " + configName
				}
				fmt.Printf("\n\nConfiguration file '%s' created.\n\nNow edit the configuration file and enter\n\n  doxygen%s\n\nto generate the documentation for your project\n\n", configName, cmdSuffix)
			}
			os.Exit(0)
		} else if arg == "-u" || strings.HasPrefix(arg, "-u") {
			configName := "Doxyfile"
			if arg == "-u" {
				if i+1 < len(args) && (!strings.HasPrefix(args[i+1], "-") || args[i+1] == "-") {
					i++
					configName = args[i]
				}
			} else {
				configName = arg[2:]
			}
			asset := "assets/Doxyfile.default"
			if shortMode {
				asset = "assets/Doxyfile.short"
			}
			err := writeAsset(asset, configName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: failed to update %s: %v\n", configName, err)
				os.Exit(1)
			}
			if configName != "-" {
				fmt.Printf("\n\nConfiguration file '%s' updated.\n\n", configName)
			}
			os.Exit(0)
		} else if arg == "-l" || strings.HasPrefix(arg, "-l") {
			layoutName := "DoxygenLayout.xml"
			if arg == "-l" {
				if i+1 < len(args) && (!strings.HasPrefix(args[i+1], "-") || args[i+1] == "-") {
					i++
					layoutName = args[i]
				}
			} else {
				layoutName = arg[2:]
			}
			err := writeAsset("assets/DoxygenLayout.xml", layoutName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", layoutName, err)
				os.Exit(1)
			}
			os.Exit(0)
		} else if arg == "-f" || strings.HasPrefix(arg, "-f") {
			spec := ""
			if arg == "-f" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-f\" is missing list specifier.\n")
					os.Exit(1)
				}
				i++
				spec = args[i]
			} else {
				spec = arg[2:]
			}
			if spec != "emoji" {
				fmt.Fprintf(os.Stderr, "error: option \"-f\" has invalid list specifier.\n")
				os.Exit(1)
			}
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "error: option \"-f emoji\" is missing an output file name\n")
				os.Exit(1)
			}
			i++
			outName := args[i]
			err := writeAsset("assets/emoji.txt", outName)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", outName, err)
				os.Exit(1)
			}
			os.Exit(0)
		} else if arg == "-w" || strings.HasPrefix(arg, "-w") {
			fmtType := ""
			if arg == "-w" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-w\" is missing format specifier rtf, html or latex\n")
					os.Exit(1)
				}
				i++
				fmtType = args[i]
			} else {
				fmtType = arg[2:]
			}
			if fmtType == "rtf" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-w rtf\" is missing a style sheet file name\n")
					os.Exit(1)
				}
				i++
				outName := args[i]
				err := writeAsset("assets/style.rtf", outName)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", outName, err)
					os.Exit(1)
				}
				os.Exit(0)
			} else if fmtType == "html" {
				if i+3 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-w html\" does not have enough arguments\n")
					os.Exit(1)
				}
				hName := args[i+1]
				fName := args[i+2]
				sName := args[i+3]
				i += 3
				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
					i++ // optional configFile
				}
				writeAsset("assets/header.html", hName)
				writeAsset("assets/footer.html", fName)
				writeAsset("assets/style.css", sName)
				os.Exit(0)
			} else if fmtType == "latex" {
				if i+3 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-w latex\" does not have enough arguments\n")
					os.Exit(1)
				}
				hName := args[i+1]
				fName := args[i+2]
				sName := args[i+3]
				i += 3
				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
					i++ // optional configFile
				}
				writeAsset("assets/header.tex", hName)
				writeAsset("assets/footer.tex", fName)
				writeAsset("assets/style.sty", sName)
				os.Exit(0)
			} else {
				fmt.Fprintf(os.Stderr, "error: Illegal format specifier \"%s\": should be one of rtf, html or latex\n", fmtType)
				os.Exit(1)
			}
		} else if arg == "-e" || strings.HasPrefix(arg, "-e") {
			fmtType := ""
			if arg == "-e" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-e\" is missing format specifier rtf.\n")
					os.Exit(1)
				}
				i++
				fmtType = args[i]
			} else {
				fmtType = arg[2:]
			}
			if fmtType == "rtf" {
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: option \"-e rtf\" is missing an extensions file name\n")
					os.Exit(1)
				}
				i++
				outName := args[i]
				err := writeAsset("assets/ext.rtf", outName)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: failed to write %s: %v\n", outName, err)
					os.Exit(1)
				}
				os.Exit(0)
			} else {
				fmt.Fprintf(os.Stderr, "error: option \"-e\" has invalid format specifier.\n")
				os.Exit(1)
			}
		} else if arg == "-x" || arg == "-x_noenv" || strings.HasPrefix(arg, "-x") {
			if arg == "-x" || arg == "-x_noenv" {
				cfgFile := ""
				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
					i++
					cfgFile = args[i]
				}
				os.Exit(compareConfig(cfgFile))
			} else {
				fmt.Fprintf(os.Stderr, "error: option should be \"-x\" or \"-x_noenv\", found: \"%s\".\n", arg)
				os.Exit(1)
			}
		} else if strings.HasPrefix(arg, "-") {
			opt := arg
			if !strings.HasPrefix(arg, "--") && len(arg) > 2 {
				opt = arg[:2]
			}
			fmt.Fprintf(os.Stderr, "error: Unknown option \"%s\"\n", opt)
			fmt.Print(getUsage(argv0))
			os.Exit(1)
		} else {
			configFile = arg
		}
	}

	_ = dLevels
	os.Exit(runDocGen(configFile, quietMode))
}
EOF"}
